UserObject.plantUmlData:
{
  "data": "@startuml
skinparam style strictuml
title Activity Diagram - Registrasi & Login (Berdasarkan SRS)

|Pengguna|
start
:Buka Halaman Web;
if (Sudah Punya Akun?) then (Belum)
  :Pilih Menu Registrasi;
  :Input Nama, Email, No HP, Password;
  |Sistem|
  :Validasi Email Unik & Simpan ke DB;
  |Pengguna|
  :Berhasil Registrasi;
else (Sudah)
endif

|Pengguna|
:Masuk ke Halaman Login;
:Input Email & Password;

|Sistem|
:Validasi Kredensial di Tabel users;
if (Data Valid?) then (Ya)
  if (Role = Admin?) then (Admin)
    :Arahkan ke Dashboard Admin;
  else (Pelanggan)
    :Arahkan ke Dashboard Pelanggan;
  endif
  stop
else (Tidak)
  :Tampilkan Pesan Error (Login Ditolak);
  |Pengguna|
  :Kembali ke Halaman Login;
  stop
endif
@enduml",
  "config": null
}

{
  "data": "@startuml
skinparam style strictuml
title Activity Diagram - Reservasi (Berdasarkan SRS)

|Pelanggan|
start
:Buka Menu Cek Jadwal;
:Pilih Lapangan, Tanggal, Jam Mulai & Selesai;
:Klik Reservasi;

|Sistem|
:Validasi Bentrok Jadwal;
if (Jadwal Bertabrakan?) then (Ya)
  :Tolak Reservasi;
  |Pelanggan|
  :Pilih Waktu/Lapangan Lain;
  stop
else (Tidak)
  |Sistem|
  :Hitung Total Harga (Durasi x Harga per Jam);
  :Simpan ke Tabel Reservasi (Status: Belum Bayar);
  |Pelanggan|
  :Melihat Halaman Tagihan & Kode Reservasi;
  stop
endif
@enduml",
  "config": null
}

{
  "data": "@startuml
skinparam style strictuml
title Activity Diagram - Pembayaran

|Pelanggan|
start
:Buka Halaman Tagihan / Riwayat Reservasi;
:Pilih Transaksi (Status: Belum Bayar);
:Isi Form Pembayaran & Upload Bukti;
:Klik Kirim Bukti Pembayaran;

|Sistem|
:Menerima File Bukti Pembayaran;
:Simpan Data ke Tabel pembayaran;
:Update Status Reservasi menjadi "Menunggu Validasi";
|Pelanggan|
:Melihat Notifikasi Sukses;
stop
@enduml",
  "config": null
}

{
  "data": "@startuml
title Activity Diagram - Validasi Pembayaran

|Admin|
start
:Buka Dashboard Admin;
:Pilih Pembayaran "Menunggu Validasi";
:Lihat Bukti Pembayaran;

|Sistem|
:Tampilkan File Bukti dari Database;

|Admin|
:Melakukan Validasi Bukti;
:Pilih Tindakan (Konfirmasi atau Tolak);

|Sistem|
if (Tindakan dari Admin?) then (Pilih Konfirmasi)
  :Update Pembayaran (Status: Lunas);
  :Update Reservasi (Status: Dikonfirmasi);
else (Pilih Tolak)
  :Update Pembayaran (Status: Ditolak);
  :Update Reservasi (Status: Ditolak);
endif

:Proses Selesai;
stop
@enduml",
  "config": null
}
